companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Process each contact
results = for contact in contacts {
    # Fix phone if needed
    phone = contact.phone if contact.phone != null else ""
    needs_phone = phone != "" and not regex.test(phone, "^\\+1\\d{10}$")
    new_phone = if needs_phone {
        digits = regex.replace(phone, "[^0-9]", "")
        # If 11 digits starting with 1, use as is with +; if 10 digits, prepend +1
        normalized = if text.length(digits) == 11 and text.starts_with(digits, "1") {
            return "+" + digits
        } else if text.length(digits) == 10 {
            return "+1" + digits
        } else if text.length(digits) == 11 {
            return "+" + digits
        } else {
            return "+1" + digits
        }
        return normalized
    } else {
        return null
    }

    # Fill company if empty
    company_empty = contact.company == null or contact.company == ""
    email = contact.email if contact.email != null else ""
    domain = if email != "" and "@" in email {
        parts = text.split(email, "@")
        return parts[1] if list.length(parts) > 1 else ""
    } else {
        return ""
    }
    new_company = if company_empty and domain != "" and domain in domain_map {
        return domain_map[domain]
    } else {
        return null
    }

    updated = if needs_phone or new_company != null {
        u = update_contact({
            id: contact.id,
            phone: new_phone if needs_phone else null,
            company: new_company if new_company != null else null
        })
        return {
            phone_fixed: needs_phone,
            company_filled: new_company != null
        }
    } else {
        return {
            phone_fixed: false,
            company_filled: false
        }
    }
    return updated
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: submit.recorded }

